package net.oceancanvas.mod.worldgen;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import it.unimi.dsi.fastutil.longs.LongOpenHashSet;import net.minecraft.core.SectionPos;import net.minecraft.world.level.ChunkPos;
final class OceanCanvasCompletedLightProofsTest {
 static void update(Object source,int x,int z){try(var publication=OceanCanvasNativeLightProofRevisions.begin(source,new LongOpenHashSet(new long[]{SectionPos.asLong(x,0,z)}),new LongOpenHashSet())){}}
 @Test void fieldMutationAfterAtomicCertificateCommitSurvivesProofRetirement(){Object source=new Object();var ledger=new OceanCanvasCompletedLightProofs();var guard=OceanCanvasNativeLightProofRevisions.watch(source,new long[]{0});long stamp=guard.stamp();assertTrue(guard.commitIfUnchanged(stamp,()->ledger.retain(0,guard,stamp)));update(source,0,0);assertTrue(ledger.takeInvalidated(0));assertEquals(0,ledger.size());assertFalse(guard.unchanged(stamp));assertFalse(ledger.takeInvalidated(0));}
 @Test void unrelatedFieldUpdateDoesNotInvalidateCompletedProof(){Object source=new Object();var ledger=new OceanCanvasCompletedLightProofs();var guard=OceanCanvasNativeLightProofRevisions.watch(source,new long[]{0});ledger.retain(0,guard,guard.stamp());update(source,4,5);assertFalse(ledger.takeInvalidated(0));assertEquals(1,ledger.size());ledger.clear();assertEquals(-1,guard.stamp());}
 @Test void boundaryNeighborChangeIsCoalescedAndUnloadReleasesGuard(){Object source=new Object();var ledger=new OceanCanvasCompletedLightProofs();var guard=OceanCanvasNativeLightProofRevisions.watch(source,new long[]{0,ChunkPos.pack(-1,0)});ledger.retain(0,guard,guard.stamp());update(source,-1,0);update(source,-1,0);assertTrue(ledger.takeInvalidated(0));var replacement=OceanCanvasNativeLightProofRevisions.watch(source,new long[]{0});ledger.retain(0,replacement,replacement.stamp());assertTrue(ledger.remove(0));assertEquals(-1,replacement.stamp());}
 @Test void saveSnapshotCanFindEveryChangedTokenWithoutWorldReferences(){Object source=new Object();var ledger=new OceanCanvasCompletedLightProofs();for(int x=0;x<4;x++){long key=ChunkPos.pack(x,0);var guard=OceanCanvasNativeLightProofRevisions.watch(source,new long[]{key});ledger.retain(key,guard,guard.stamp());}update(source,3,0);int dirty=0;for(long key:ledger.chunks())if(ledger.takeInvalidated(key))dirty++;assertEquals(1,dirty);assertEquals(3,ledger.size());ledger.clear();}
}
